<?php /** @var array $m @var array $members @var array $decisions */ ?>
<div class="page-head"><div><h1><?= icon('users') ?> <?= e($m['body_name']) ?> — <?= e(fdate($m['meeting_date'])) ?></h1><p class="sub"><span class="badge <?= $m['status'] === 'held' ? ($m['quorum_met'] ? 'ok' : 'danger') : 'warn' ?>"><?= e(t('enum.mstatus.' . $m['status'])) ?></span><?php if ($m['status'] === 'held'): ?> <span class="badge <?= $m['quorum_met'] ? 'ok' : 'danger' ?>"><?= e(t($m['quorum_met'] ? 'gov.quorum_met' : 'gov.quorum_missing')) ?> (<?= (int)$m['present_count'] ?>/<?= (int)$m['members_count'] ?>)</span><?php endif; ?></p></div>
  <div class="actions"><a class="btn secondary" href="<?= e(url('governance/' . $m['body_id'])) ?>"><?= e(t('common.back')) ?></a></div></div>
<?php if ($m['agenda']): ?><section class="card"><h2><?= e(t('gov.m_agenda')) ?></h2><p class="pre"><?= e($m['agenda']) ?></p></section><?php endif; ?>
<?php if ($m['status'] === 'planned' && can('governance.manage')): ?><section class="card"><h2><?= e(t('gov.record_meeting')) ?></h2><p class="muted"><?= e(t('gov.record_hint', ['q' => (int)$m['quorum_percent']])) ?></p>
<form method="post" action="<?= e(url('governance/meetings/' . $m['id'] . '/hold')) ?>" novalidate><?= csrf_field() ?>
<fieldset><legend><?= e(t('gov.attendance')) ?></legend><?php foreach ($members as $x): ?><label class="check"><input type="checkbox" name="present[<?= (int)$x['user_id'] ?>]" value="1"> <?= e($x['full_name']) ?> <span class="badge"><?= e(t('enum.grole.' . $x['member_role'])) ?></span></label><?php endforeach; ?></fieldset>
<?= ff('textarea', 'minutes', 'gov.m_minutes', '', ['required' => true, 'extra' => ' rows="8"', 'hint' => t('gov.m_minutes_hint')]) ?>
<div class="actions"><button class="btn" type="submit"><?= e(t('gov.save_held')) ?></button></div></form>
<form method="post" action="<?= e(url('governance/meetings/' . $m['id'] . '/cancel')) ?>" data-confirm="<?= e(t('gov.confirm_cancel')) ?>" style="margin-top:8px"><?= csrf_field() ?><button class="btn danger" type="submit"><?= e(t('gov.cancel_meeting')) ?></button></form></section><?php endif; ?>
<?php if ($m['status'] === 'held'): ?><section class="card"><h2><?= e(t('gov.attendance')) ?></h2><ul class="task-list"><?php foreach ($members as $x): ?><li><span><?= e($x['full_name']) ?></span><span class="badge <?= $x['present'] ? 'ok' : 'danger' ?>"><?= e(t($x['present'] ? 'gov.present' : 'gov.absent')) ?></span></li><?php endforeach; ?></ul></section>
<section class="card"><h2><?= e(t('gov.m_minutes')) ?></h2><p class="pre"><?= e($m['minutes']) ?></p></section>
<section class="card"><h2><?= e(t('gov.decisions')) ?></h2><?php if (!$decisions): ?><p class="muted"><?= e(t('gov.no_decisions')) ?></p><?php else: ?><ul class="task-list"><?php foreach ($decisions as $d): ?><li><a href="<?= e(url('committees/' . $d['id'])) ?>"><?= e($d['code'] . ' — ' . $d['title']) ?></a></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
